def law(label,original,key,kp,base='10',expand=True,domain=None):
 expr=('expand(expand_log(('+original+'),force=True))'if expand else'logcombine(expand(('+original+')*log('+base+')),force=True)/log('+base+')')
 p=v(label,expr,key,kp,'Apply product,quotient and power laws to the ORIGINAL expression with a COMMON valid base. The symbolic force-normalisation is warranted ONLY on the explicitly recorded positive-factor comparison branch; it is not a proof that real logarithms of negative factors exist. Preserve the original domain when compressing, and record any broader-domain alternative when expanding. Constants must first be expressed as logs of powers of this same base; no change-of-base learner method is requested.')
 p.update(original_expression=original,assessed_8227_demand_ids=[LAW],response_format='symbolic',original_domain=domain or'All source logarithm arguments must be positive; any denominator nonzero; base positive and not1.',source_answer_domain='Positive factors inside every separately printed logarithm. This comparison branch is explicit; it does not silently replace the original expression domain.',source_base=base)
 return p
